// Try multiple approaches to find the share trigger
function findShareTrigger() {
  // Approach 1: Find by data attribute
  const byAttr = document.querySelector('[data-tracking-control-name*="share"]');
  if (byAttr) return byAttr;

  // Approach 2: Find the share box container and click its main button
  const shareContainers = document.querySelectorAll('.share-box-feed-entry, .share-box, [class*="share-box"]');
  for (const sc of shareContainers) {
    const btn = sc.querySelector('button');
    if (btn) return btn;
  }

  // Approach 3: Find button with "Start a post" text
  for (const el of document.querySelectorAll('button, span, div[role="button"]')) {
    if (el.textContent?.trim() === 'Start a post') return el;
  }

  // Approach 4: Find any element with "Start a post" text that looks clickable
  for (const el of document.querySelectorAll('*')) {
    if (el.childNodes.length === 1 && el.childNodes[0].nodeType === 3 && el.textContent?.trim() === 'Start a post') {
      return el.closest('button') || el.parentElement?.closest('button') || el;
    }
  }

  return null;
}

