// Try to create a LinkedIn share via the Voyager API
// The CSRF token is available in the page's JS runtime

async function postToLinkedIn() {
  // Get CSRF from meta tag or global JS variable
  let csrf = '';
  const metaEl = document.querySelector('meta[name="csrf-token"]');
  if (metaEl) csrf = metaEl.getAttribute('content');

  // LinkedIn stores auth state in various places
  if (!csrf) {
    // Try parsing it from the page's script tags
    const scripts = document.querySelectorAll('script');
    for (const s of scripts) {
      const match = s.textContent?.match(/csrfToken["']?\s*:\s*["']([^"']+)["']/);
      if (match) { csrf = match[1]; break; }
    }
  }

  if (!csrf) {
    return 'NO_CSRF: meta=' + !!metaEl + ' scripts=' + document.querySelectorAll('script').length;
  }

  const body = {
    commentary: '🤖 AI News Roundup — 8 Things You Need to Know Today\n\n🔒 The White House refused a direct UK request for a Fable 5 carve-out — calling exceptions for allied nations "completely illogical" and confirming the Anthropic export ban is global with no off-ramp in sight.\n\n☁️ Microsoft CEO Satya Nadella warned enterprises against AI lock-in, posting that companies must build agentic systems that "retain their own IP rather than ceding value to a few models that eat everything they see."\n\n📈 Chinese open-source AI labs MiniMax and Zhipu (now Z.ai) both surged on markets Monday as the Fable 5 situation made the business case for open weights tangible.\n\n💰 Ramp raised ~$750M in a growth round for AI-powered spend management and financial operations.\n\n🎵 Suno closed a $400M Series D led by BOND for AI music generation.\n\n🧪 PhysicsX raised $300M Series C led by Temasek for AI-driven physics simulation.\n\n🛡️ President Trump signed an AI executive order on June 2 targeting frontier model security, cybersecurity, and criminal use of AI.\n\n🚫 Google killed Gemini CLI for free, Pro, and Ultra users today — the Apache 2.0 project with 6,000 merged community PRs and 100K GitHub stars shut down hard.\n\nGenerated with Wolffish 🐟',
    visibility: 'PUBLIC'
  };

  try {
    const resp = await fetch('/voyager/api/voyagerDashShares?action=create', {
      method: 'POST',
      headers: {
        'csrf-token': csrf,
        'Content-Type': 'application/json',
        'x-restli-protocol-version': '2.0.0'
      },
      body: JSON.stringify(body)
    });
    const text = await resp.text();
    return 'API_RESPONSE: ' + resp.status + ' ' + text.substring(0, 300);
  } catch(e) {
    return 'API_ERROR: ' + e.message;
  }
}

